function csvRows(body: string): string[][] {
  return body
    .split(/\r?\n/)
    .filter((l) => l.trim())
    .map((l) => l.split(',').map((c) => c.trim()));
}

// ---------------------------------------------------------------- router

function json(route: Route, body: unknown, status = 200) {
  return route.fulfill({ status, json: body });
}

export async function mockResearchApi(page: Page): Promise<void> {
  await page.route('**/api/v1/**', async (route) => {
    const req = route.request();
    const url = new URL(req.url());
    const path = url.pathname.replace(/^\/api\/v1/, '');
    const method = req.method();
    const q = url.searchParams;
    const seg = path.split('/').filter(Boolean).map(decodeURIComponent);

    // Studies
    if (path === '/studies' && method === 'GET')
      return json(route, [
        STUDY,
        {
          ...STUDY,
          study_id: 'S-PILOT',
          code: 'S1',
          name: 'Think-aloud pilot (hi-IN, mr-IN)',
          stage: 'think_aloud',
          status: 'draft',
          target_sample: 40,
          created_at: iso(40 * DAY),
          prereg_id: null,
          requires_prereg: false,
        },
      ]);
    if (seg[0] === 'studies' && seg[1]) {
      const sid = seg[1];
      const own = sid === DEMO_STUDY_ID;
      if (seg.length === 2 && method === 'GET') {
        if (!own)
          return json(route, {
            study: {
              ...STUDY,
              study_id: sid,
              code: 'S1',
              name: 'Think-aloud pilot (hi-IN, mr-IN)',
              status: 'draft',
            },
            protocols: [],
            cohorts: [],
            arms: [],
            occasions: [],
            quotas: [],
            analysis_plans: [],
          });
        return json(route, {
          study: STUDY,
          protocols: [
            {
              version: 'S2-pilot-v1',
              document_sha256: sha('demo protocol'),
              summary: 'Demo protocol',
              effective_from: iso(21 * DAY),
              approved_by: ['Dr A. Rao (PI)', 'S. Iyer (Ethics)'],
            },
          ],
          cohorts: [
            { cohort_id: 'main', name: 'Main pilot cohort', criteria: {}, holdout: false },
            { cohort_id: 'holdout', name: 'Untouched holdout cohort', criteria: {}, holdout: true },
          ],
          arms: [
            { arm_id: 'B_fixed', ratio: 1, description: 'Pathway B micro-game carousel' },
            { arm_id: 'A_narrative', ratio: 1, description: 'Pathway A linked episodes' },
          ],
          occasions: [
            {
              occasion_id: 'T1',
              wave: 1,
              label: 'Baseline',
              sequence: 1,
              offset_days_min: null,
              offset_days_max: null,
              instruments: ['bscs', 'bfi2_xs', 'grit_s', 'ders16', 'hexaco_hh', 'gdms'],
              game_required: true,
            },
            {
              occasion_id: 'T2',
              wave: 1,
              label: 'Retest',
              sequence: 2,
              offset_days_min: 14,
              offset_days_max: 28,
              instruments: ['bfi2_xs', 'bscs', 'grit_s'],
              game_required: true,
            },
          ],
          quotas: QUOTAS,
          analysis_plans: [
            {
              plan_id: uuid('plan-demo'),
              version: '0.1.0',
              prereg_id: 'demo-prereg',
              hypotheses_sha256: HYP_SHA,
              gates_sha256: GATES_SHA,
              registered_at: iso(20 * DAY),
            },
          ],
        });
      }
      if (seg[2] === 'quotas' && method === 'GET') return json(route, own ? QUOTAS : []);
      if (seg[2] === 'enrollments' && method === 'GET') return json(route, own ? ENROLLMENTS : []);
      if (seg[2] === 'deviations' && method === 'GET') return json(route, own ? DEVIATIONS : []);
      if (seg[2] === 'deviations' && method === 'POST') {
        const body = rec(req.postDataJSON());
        const row = {
          id: DEVIATIONS.length + 1,
          ...body,
          reported_by: 'dev-researcher',
          created_at: new Date(NOW).toISOString(),
        };
        DEVIATIONS.push(row);
        return json(route, { ...row, study_id: sid }, 201);
      }
      if (seg[2] === 'retests' && seg.length === 3 && method === 'POST') {
        const body = rec(req.postDataJSON());
        const anchors = rec(body.anchors);
        return json(route, {
          scheduled: Object.entries(anchors).map(([pid, d]) => ({
            pid,
            occasion_id: body.occasion_id,
            window_start: new Date(Date.parse(String(d)) + 14 * DAY).toISOString().slice(0, 10),
            window_end: new Date(Date.parse(String(d)) + 28 * DAY).toISOString().slice(0, 10),
            status: 'scheduled',
          })),
          refused: [],
        });
      }
      if (seg[2] === 'analysis-plans' && method === 'POST') {
        const body = rec(req.postDataJSON());
        return json(
          route,
          {
            plan_id: uuid(`plan-${String(body.version)}`),
            study_id: sid,
            version: body.version,
            hypotheses_sha256: HYP_SHA,
            gates_sha256: GATES_SHA,
          },
          201,
        );
      }
      if (seg[2] === 'freeze' && method === 'POST')
        return json(route, {
          study_id: sid,
          frozen_at: new Date(NOW).toISOString(),
          snapshot_ids: [SNAPSHOT_ID],
        });
      if (method === 'POST' || method === 'PATCH')
        return json(
          route,
          { study_id: sid, ...rec(req.postDataJSON()) },
          method === 'POST' ? 201 : 200,
        );
    }
    if (path === '/studies' && method === 'POST')
      return json(
        route,
        {
          ...STUDY,
          ...rec(req.postDataJSON()),
          status: 'draft',
          created_at: new Date(NOW).toISOString(),
        },
        201,
      );

    // Sessions
    if (path === '/sessions' && method === 'GET') {
      const sid = q.get('study_id');
      const rows = SESSIONS.filter((s) => !sid || s.study_id === sid);
      const limit = Number(q.get('limit') ?? 100);
      const offset = Number(q.get('offset') ?? 0);
      return json(route, {
        items: rows.slice(offset, offset + limit),
        total: rows.length,
        limit,
        offset,
      });
    }

    // Participants
    if (path === '/participants' && method === 'GET') {
      const sid = q.get('study_id');
      const rows = PEOPLE.filter(() => !sid || sid === DEMO_STUDY_ID).map((p) => ({
        pid: p.pid,
        study_id: DEMO_STUDY_ID,
        source: 'kiosk_pairing',
        status: p.status,
        created_at: p.created,
        withdrawn_at: p.status === 'withdrawn' ? iso(2 * DAY) : null,
      }));
      const limit = Number(q.get('limit') ?? 100);
      const offset = Number(q.get('offset') ?? 0);
      return json(route, {
        items: rows.slice(offset, offset + limit),
        total: rows.length,
        limit,
        offset,
      });
    }
    if (path === '/participants/erasure-requests' && method === 'POST') {
      const body = rec(req.postDataJSON());
      return json(
        route,
        {
          request_id: uuid(`erasure-${String(body.pid)}`),
          scope: body.scope,
          pid_hmac: sha(String(body.pid)).slice(0, 32),
          session_id: null,
          channel: body.channel ?? 'administrator',
          status: 'requested',
          job_id: uuid('erasure-job'),
          created_at: new Date(NOW).toISOString(),
          completed_at: null,
          error: null,
          receipt: null,
        },
        202,
      );
    }
    if (seg[0] === 'participants' && seg[1] && seg[1] !== 'link') {
      const p = PEOPLE.find((x) => x.pid === seg[1]);
      if (!p)
        return json(
          route,
          { detail: { code: 'unknown_pid', message: 'participant not found' } },
          404,
        );
      const out = {
        pid: p.pid,
        study_id: DEMO_STUDY_ID,
        source: 'kiosk_pairing',
        status: p.status,
        created_at: p.created,
        withdrawn_at: p.status === 'withdrawn' ? iso(2 * DAY) : null,
      };
      if (seg.length === 2) {
        const links = SESSIONS.filter((s) => s.participant_pid === p.pid).map((s, k) => ({
          id: k + 1,
          pid: p.pid,
          session_id: s.session_id,
          study_id: DEMO_STUDY_ID,
          occasion_id: s.occasion_id,
          visit_number: s.occasion_id === 'T2' ? 2 : 1,
          method: k % 2 ? 'qr_token' : 'pairing_code',
          linked_by: 'kiosk-1',
          second_linker: null,
          created_at: s.started_at,
        }));
        return json(route, {
          participant: out,
          links,
          consent: {
            core: true,
            criterion: true,
            archive: p.pid.charCodeAt(0) % 2 === 0,
            contact: p.retest,
            research_audio: false,
          },
          enrollments: [
            {
              study_id: DEMO_STUDY_ID,
              cohort_id: p.cohort,
              arm_id: p.arm,
              criterion_block: p.block,
              status: p.status === 'withdrawn' ? 'withdrawn' : 'enrolled',
            },
          ],
        });
      }
      if (seg[2] === 'consents' && method === 'GET') {
        return json(
          route,
          ['core', 'criterion', 'archive', 'contact'].map((kind, k) => ({
            consent_id: uuid(`consent-${p.pid}-${kind}`),
            participant_pid: p.pid,
            session_id: SESSIONS.find((s) => s.participant_pid === p.pid)?.session_id ?? null,
            kind,
            granted:
              kind === 'core' ||
              kind === 'criterion' ||
              (kind === 'contact' && p.retest) ||
              (kind === 'archive' && p.pid.charCodeAt(0) % 2 === 0),
            consent_script_id: `consent.${kind}.v2`,
            script_audio_sha256: sha(`${kind}-audio`),
            language: p.language,
            policy_version: '2026-09',
            protocol_id: 'S2-pilot-v1',
            input_mode: k % 2 ? 'voice_then_touch_confirm' : 'touch',
            presented_at: p.created,
            decided_at: p.created,
            kiosk_id: 'kiosk-1',
            replay_counts: [0, 1],
            supersedes_id: null,
            recorded_by: 'kiosk-1',
            created_at: p.created,
          })),
        );
      }
      if (seg[2] === 'withdraw' && method === 'POST') {
        const body = rec(req.postDataJSON());
        p.status = 'withdrawn';
        return json(route, {
          pid_hmac: sha(p.pid).slice(0, 32),
          scope: body.scope,
          erasure_request_id: body.scope === 'withdraw_and_erase' ? uuid(`erasure-${p.pid}`) : null,
        });
      }
    }
    if (seg[0] === 'participants' && seg[1] === 'erasure-requests' && seg[2]) {
      return json(route, {
        request_id: seg[2],
        scope: 'participant',
        pid_hmac: 'b1c9…',
        session_id: null,
        channel: 'administrator',
        status: 'completed',
        job_id: uuid('erasure-job'),
        created_at: iso(60_000),
        completed_at: new Date(NOW).toISOString(),
        error: null,
        receipt: {
          receipt_id: uuid('receipt'),
          body: { tables: 14, rows: 311 },
          signature: 'MEUCIQ…',
          key_id: 'ed25519-2026-10',
          algorithm: 'ed25519',
          issued_at: new Date(NOW).toISOString(),
        },
      });
    }

    // Matched records
    if (path === '/validation/matched-records')
      return json(route, q.get('study_id') === DEMO_STUDY_ID ? MATCHED : []);

    // Instruments
    if (path === '/instruments' && method === 'GET') return json(route, INSTRUMENTS);
    if (seg[0] === 'instruments' && seg[1]) {
      const inst = INSTRUMENTS.find((i) => i.instrument_id === seg[1]);
      if (!inst) return json(route, { detail: 'instrument not found' }, 404);
      if (seg.length === 2) return json(route, inst);
      if (seg[2] === 'versions' && seg.length === 3) {
        const d = versionDetail(inst.instrument_id) as Json;
        return json(route, [
          {
            instrument_id: inst.instrument_id,
            version: d.version,
            key_version: d.key_version,
            status: 'active',
            source_path: d.source_path,
            created_at: d.created_at,
          },
          {
            instrument_id: inst.instrument_id,
            version: '0.9.0',
            key_version: '0.9.0',
            status: 'superseded',
            source_path: d.source_path,
            created_at: iso(60 * DAY),
          },
        ]);
      }
      if (seg[2] === 'versions' && seg[3]) return json(route, versionDetail(inst.instrument_id));
      if (seg[2] === 'licensing' && method === 'GET')
        return json(route, [
          inst.licensing,
          {
            ...inst.licensing,
            id: 1,
            permission_status: 'not_requested',
            created_at: iso(60 * DAY),
            permission_document: null,
          },
        ]);
      if (seg[2] === 'licensing' && method === 'POST')
        return json(
          route,
          {
            ...inst.licensing,
            ...rec(req.postDataJSON()),
            created_at: new Date(NOW).toISOString(),
          },
          201,
        );
    }

    // Assessment responses / imports
    if (path === '/assessment-responses' && method === 'POST') {
      const body = rec(req.postDataJSON());
      const runId = uuid(`scoring-${String(body.pid)}-${String(body.instrument_id)}`);
      return json(
        route,
        {
          responses: arr(body.responses)
            .map(rec)
            .map((r) => ({
              response_id: uuid(`resp-${String(r.item_id)}`),
              pid: body.pid,
              subject_pid: body.pid,
              study_id: body.study_id,
              wave: body.wave,
              occasion_id: body.occasion_id,
              instrument_id: body.instrument_id,
              instrument_version: body.instrument_version,
              language_version: body.language,
              block: body.block,
              item_id: r.item_id,
              raw_response: r.raw_response,
              response_latency_ms: r.response_latency_ms,
              administration_mode: body.administration_mode,
              administrator_id: body.administrator_id,
              rater_role: body.rater_role,
              rated_pid: body.rated_pid,
              device_id: body.device_id,
              audio_version: body.audio_version,
              attention_check: false,
              attention_check_failed: null,
              planned_missing_items: body.planned_missing_items,
              source: 'in_app',
              recorded_at: new Date(NOW).toISOString(),
              supersedes_id: null,
              correction_reason: null,
              submitted_by: 'dev',
            })),
          scoring_run_id: runId,
          scores: null,
        },
        201,
      );
    }
    if (path === '/assessment-responses/imports' && method === 'POST') {
      const raw = req.postData() ?? '';
      const specMatch = /name="spec"\r?\n\r?\n([\s\S]*?)\r?\n--/.exec(raw);
      const fileMatch = /filename="([^"]*)"[\s\S]*?\r?\n\r?\n([\s\S]*?)\r?\n--/.exec(raw);
      const spec = rec(JSON.parse(specMatch?.[1] ?? '{}'));
      const filename = fileMatch?.[1] ?? 'upload.csv';
      const rows = csvRows(fileMatch?.[2] ?? '');
      const [header = [], ...data] = rows;
      const mapping = rec(spec.column_mapping);
      const pidCol = header.indexOf(String(mapping.pid ?? ''));
      const known = new Set(PEOPLE.map((p) => p.pid));
      const staged = data.map((r, k) => {
        const pid = pidCol >= 0 ? (r[pidCol] ?? '') : '';
        const values: Json = {};
        const issues: Json[] = [];
        for (const [key, col] of Object.entries(mapping)) {
          if (!key.startsWith('item:')) continue;
          const v = r[header.indexOf(String(col))] ?? '';
          const n = v === '' ? null : Number(v);
          values[key.slice(5)] = n;
          if (n !== null && (!Number.isFinite(n) || n < 1 || n > 5))
            issues.push({ code: 'out_of_range', item_id: key.slice(5), value: v });
        }
        if (!known.has(pid)) issues.push({ code: pid ? 'unknown_pid' : 'missing_pid', value: pid });
        return {
          row_number: k + 1,
          pid: pid || null,
          values,
          status: issues.length ? 'needs_review' : 'ready',
          issues,
          resolved_by: null,
          resolved_at: null,
          resolution_note: null,
        };
      });
      const id = uuid(`import-${filename}-${IMPORTS.size}`);
      const out = {
        import_id: id,
        study_id: spec.study_id,
        instrument_id: spec.instrument_id,
        instrument_version: spec.instrument_version ?? '1.0.0',
        language: spec.language,
        occasion_id: spec.occasion_id,
        wave: spec.wave ?? 1,
        block: spec.block,
        filename,
        file_format: filename.endsWith('.xlsx') ? 'xlsx' : 'csv',
        file_sha256: sha(fileMatch?.[2] ?? ''),
        column_mapping: mapping,
        status: 'staged',
        counts: {
          rows: staged.length,
          ready: staged.filter((s) => s.status === 'ready').length,
          needs_review: staged.filter((s) => s.status === 'needs_review').length,
        },
        created_by: 'dev-researcher',
        created_at: new Date(NOW).toISOString(),
        committed_at: null,
      };
      IMPORTS.set(id, { out, rows: staged });
      return json(route, out, 201);
    }
    if (seg[0] === 'assessment-responses' && seg[1] === 'imports' && seg[2]) {
      const st = IMPORTS.get(seg[2]);
      if (!st) return json(route, { detail: 'import not found' }, 404);
      const recount = () => {
        st.out.counts = {
          rows: st.rows.length,
          ready: st.rows.filter((r) => r.status === 'ready' || r.status === 'approved').length,
          needs_review: st.rows.filter((r) => r.status === 'needs_review').length,
          rejected: st.rows.filter((r) => r.status === 'rejected').length,
        };
      };
      if (seg.length === 3) return json(route, st.out);
      if (seg[3] === 'rows' && seg.length === 4) return json(route, st.rows);
      if (seg[3] === 'rows' && seg[5] === 'resolve') {
        const body = rec(req.postDataJSON());
        const row = st.rows.find((r) => String(r.row_number) === seg[4]);
        if (row)
          Object.assign(row, {
            status: body.action === 'approve' ? 'approved' : 'rejected',
            resolved_by: 'dev-researcher',
            resolved_at: new Date(NOW).toISOString(),
            resolution_note: body.note ?? null,
            ...(body.pid ? { pid: body.pid } : {}),
          });
        recount();
        return json(route, row);
      }
      if (seg[3] === 'commit') {
        st.out.status = 'committed';
        st.out.committed_at = new Date(NOW).toISOString();
        recount();
        return json(route, st.out);
      }
      if (seg[3] === 'cancel') {
        st.out.status = 'cancelled';
        return json(route, st.out);
      }
    }

    // Features / traits
    if (path === '/features/constructs') return json(route, CONSTRUCTS);
    if (path === '/features/definitions') return json(route, INDICATOR_DEFS);
    if (path === '/features/feature-definitions') return json(route, FEATURE_DEFS);
    if (path === '/features')
      return json(route, q.get('study_id') === DEMO_STUDY_ID ? INDICATOR_VALUES : []);
    if (path === '/features/group-indicators') return json(route, []);

    // Validation
    if (path === '/validation/datasets' && method === 'GET')
      return json(route, q.get('study_id') === DEMO_STUDY_ID ? DATASETS : []);
    if (path === '/validation/datasets' && method === 'POST') {
      const body = rec(req.postDataJSON());
      return json(
        route,
        { ...snapshot(uuid(`snap-${String(body.name)}`), 3, 'building', 0), name: body.name },
        202,
      );
    }
    if (seg[0] === 'validation' && seg[1] === 'datasets' && seg[2]) {
      const snap = DATASETS.find((d) => d.snapshot_id === seg[2]);
      if (!snap) return json(route, { detail: 'snapshot not found' }, 404);
      if (seg.length === 3) return json(route, snap);
      if (seg[3] === 'download') {
        return route.fulfill({
          status: 200,
          body: PARQUET,
          headers: { 'content-type': 'application/vnd.apache.parquet' },
        });
      }
      if (seg[3] === 'freeze')
        return json(route, { ...snap, status: 'frozen', frozen_at: new Date(NOW).toISOString() });
      if (seg[3] === 'gate-evaluation') return json(route, GATE_RUN, 201);
    }
    if (path === '/validation/runs' && method === 'GET') {
      const rows = q.get('snapshot_id') === SNAPSHOT_ID ? ALL_RUNS : [];
      return json(
        route,
        rows.map((r) => ({ ...r, results: null })),
      );
    }
    if (path === '/validation/runs' && method === 'POST') {
      const body = rec(req.postDataJSON());
      return json(
        route,
        {
          ...(RUNS[0] as Json),
          run_id: uuid(`queued-${String(body.analysis)}-${Date.now()}`),
          analysis: body.analysis,
          status: 'queued',
          results: null,
          finished_at: null,
        },
        202,
      );
    }
    if (seg[0] === 'validation' && seg[1] === 'runs' && seg[2]) {
      const run = ALL_RUNS.find((r) => r.run_id === seg[2]);
      return run ? json(route, run) : json(route, { detail: 'run not found' }, 404);
    }

    // Models
    if (path === '/models' && method === 'GET')
      return json(
        route,
        MODELS.map((m) => m.out),
      );
    if (seg[0] === 'models' && seg[1]) {
      const m = MODELS.find((x) => x.out.model_id === seg[1]);
      if (!m) return json(route, { detail: 'model not found' }, 404);
      if (seg.length === 2) return json(route, m.out);
      if (seg[2] === 'evaluations') return json(route, evaluations(m.fx, m.out.model_id));
      if (seg[2] === 'training-runs') {
        return json(route, [
          {
            run_id: uuid(`training-${m.out.model_id}`),
            model_id: m.out.model_id,
            job_id: uuid(`job-train-${m.out.model_id}`),
            status: 'succeeded',
            engine: ENGINE.engine,
            metrics: {
              cv: Object.fromEntries(
                Object.entries(rec(m.fx.cv_metrics)).map(([k, v]) => [k, rec(v).mean]),
              ),
              holdout: m.fx.holdout_metrics,
              n_train: m.fx.n_train,
              n_holdout: m.fx.n_holdout,
              cv_scheme: rec(m.fx.details).cv_scheme,
              leakage_check: rec(m.fx.details).leakage_check,
              provenance: {
                ...rec(rec(m.fx.details).provenance),
                snapshot_id: SNAPSHOT_ID,
                git_sha: GIT_SHA,
              },
            },
            error: null,
            created_at: m.out.created_at,
            finished_at: m.out.created_at,
          },
        ]);
      }
      if (seg[2] === 'predictions') return json(route, arr(m.fx.predictions));
    }
    if (path === '/models' && method === 'POST')
      return json(
        route,
        {
          run_id: uuid('new-training'),
          model_id: uuid('new-model'),
          job_id: null,
          status: 'queued',
          engine: null,
          metrics: {},
          error: null,
          created_at: new Date(NOW).toISOString(),
          finished_at: null,
        },
        202,
      );

    // Norms
    if (path === '/norms/tables' && method === 'GET') {
      return json(
        route,
        LANGS.flatMap((language) =>
          ['self_control', 'risk_preference'].map((trait) => ({
            id: uuid(`norm-${trait}-${language}`),
            norm_table_version: 'demo-0001',
            trait,
            pathway: 'B',
            language,
            reference_population_id: null,
            cut_points: [-0.43, 0.41],
            sem: 0.47,
            ci_level: 0.9,
            provisional: true,
            effective_n: 160,
            method: 'empirical_quantiles',
            coefficients: {},
            status: 'draft',
            approved_by: [],
            algorithm_version: '0.2.0',
            data_snapshot_id: SNAPSHOT_ID,
          })),
        ),
      );
    }

    // Gates / admin reads used by research pages
    if (path === '/admin/gates' && method === 'GET') return json(route, GATES);
    if (path === '/admin/gates/trait' && method === 'POST') {
      const body = rec(req.postDataJSON());
      const row = {
        id: GATES.trait_history.length + 10,
        ...body,
        effective_from: new Date(NOW).toISOString(),
        gates_version: '0.1.0',
        recorded_by: 'dev-admin',
        created_at: new Date(NOW).toISOString(),
      } as Json;
      GATES.trait_history.push(row as never);
      return json(route, row, 201);
    }
    if (path === '/admin/content-versions' && method === 'GET') {
      return json(route, [
        {
          id: uuid('cv-dict'),
          kind: 'dictionary',
          version: dictVersion,
          sha256: DICT_SHA.B,
          status: 'draft',
          approved_by: [],
          created_at: iso(5 * DAY),
        },
        {
          id: uuid('cv-gates'),
          kind: 'gates',
          version: '0.1.0',
          sha256: GATES_SHA,
          status: 'draft',
          approved_by: [],
          created_at: iso(5 * DAY),
        },
        {
          id: uuid('cv-hyp'),
          kind: 'hypotheses',
          version: '0.1.0',
          sha256: HYP_SHA,
          status: 'draft',
          approved_by: [],
          created_at: iso(5 * DAY),
        },
      ]);
    }
    return route.fallback();
  });
}
